python3 - <<'PYEOF'
import os, sys
fn = 'cosserat2d_mob.edp'
s = open(fn).read()
if 'bckin' in s: sys.exit(fn + ': already has -bckin')
if 'spinbranch' not in s: sys.exit(fn + ': apply the spin-branch patch first')
P = [('real spinMax = atof(arg("-spinmax", "0"));      // >0: bound |dw*| per step (rad), like the drag bound on slip; 0 = off (default)\n// -spinbranch b (rad, 0 = off = old): |dw*| <= b per step in the spin update AND the polish. The energy is pi-periodic in w* with the\n//   exact exponential, so dw* = k tau*(dw*) has spurious roots near n pi in GB cores; b = pi/4 never binds a physical increment (~1e-3 rad).\nreal spinBranch = atof(arg("-spinbranch", "0"));\n', 'real spinMax = atof(arg("-spinmax", "0"));      // >0: bound |dw*| per step (rad), like the drag bound on slip; 0 = off (default)\n// -spinbranch b (rad, 0 = off = old behaviour): keep the GB-spin increment on the principal root, |dw*| <= b per step, in the\n//   spin update AND in the coupled polish.  With the exact exponential the energy is pi-periodic in w* (Ubar -> -Ubar leaves\n//   Ubar^T Ubar and a^2 unchanged), so dw* = k tau*(dw*) has spurious roots at ~n pi wherever k = dt(1-phi)^2/(2 eta*0) is large\n//   (GB cores); the local Newton can land on one (2026-10-31: w* 0.001 -> 71.8 rad in one step, T -> 6e5 K, 50 m/s at 3.96 ns).\n//   b = pi/4 never binds a physical increment (|dw*| ~ 1e-3 rad per step) but excludes every spurious root.\nreal spinBranch = atof(arg("-spinbranch", "0"));\n'), ('      tmp = tstar .* kspin; tmp -= dwst; rsp = tmp.linfty; tmp2 = kspin; tmp2 *= 4*muc; tmp2 += 1; tmp = tmp ./ tmp2;\n      if (spinCap > 0) { real[int] dold = dwst; dwst += tmp; real[int] smx(nt); smx = spinCap; clampv(dwst, smx); tmp = dwst - dold; }   // -spinmax: |dw*| <= spinMax per step\n      else dwst += tmp;\n', '      tmp = tstar .* kspin; tmp -= dwst; rsp = tmp.linfty; tmp2 = kspin; tmp2 *= 4*muc; tmp2 += 1; tmp = tmp ./ tmp2;\n      if (spinCap > 0) { real[int] dold = dwst; dwst += tmp; real[int] smx(nt); smx = spinCap; clampv(dwst, smx); tmp = dwst - dold; }   // -spinmax / -spinbranch: |dw*| <= cap per step\n      else dwst += tmp;\n'), ('real[int] mask(Wh.ndof); mask = 1; mask -= bcm;\n// KWC couple stress from element-mean phi^2 (consistent with the energy)\n', 'real[int] mask(Wh.ndof); mask = 1; mask -= bcm;\n// -bckin 1 (2026-10-31; 0 = old): the prescribed dofs (piston face u_x, rollers u_y, wall u_x) carry their exact prescribed velocity and\n//   acceleration instead of the Newmark recursion.  On a dof whose displacement is prescribed, a_{n+1} = c0 (U-Un) - c1 v_n - a_n with\n//   U - Un = 0 makes v flip sign every step and a grow linearly (4|v|/dt per step); through the consistent mass these dofs then drive\n//   their free neighbours with a growing alternating force (50 m/s: |a| = 4.6e3 um/ns^2 at 6.2 ns -> kink at the piston face, Newton diverged).\nint bcKin = atoi(arg("-bckin", "0"));\nstring predName = arg("-predictor", "avg");\nfunc real pistonVel(real tt) {   // d/dt pistonDisp = u_p e(t)\n  real s;\n  if (tt <= 0) return 0.;\n  if (tt < pistTr) { s = tt/pistTr; return pistUp*(6*s^5 - 15*s^4 + 10*s^3); }\n  if (tt < pistTr + pistTh) return pistUp;\n  if (tt < 2*pistTr + pistTh) { s = (tt - pistTr - pistTh)/pistTr; return pistUp*(1 - (6*s^5 - 15*s^4 + 10*s^3)); }\n  return 0.;\n}\nfunc real pistonAcc(real tt) {\n  real s;\n  if (tt <= 0) return 0.;\n  if (tt < pistTr) { s = tt/pistTr; return pistUp/pistTr*(30*s^4 - 60*s^3 + 30*s^2); }\n  if (tt < pistTr + pistTh) return 0.;\n  if (tt < 2*pistTr + pistTh) { s = (tt - pistTr - pistTh)/pistTr; return -pistUp/pistTr*(30*s^4 - 60*s^3 + 30*s^2); }\n  return 0.;\n}\nfunc int fixBCkin(real tt) {   // V, Acc on the prescribed dofs := exact (piston: -v_p, -a_p in x; every other prescribed dof: 0)\n  V = V .* mask; Acc = Acc .* mask;\n  if (isP) { real[int] q = pistm; q *= -pistonVel(tt); V += q; q = pistm; q *= -pistonAcc(tt); Acc += q; }\n  return 0;\n}\n// KWC couple stress from element-mean phi^2 (consistent with the energy)\n'), ('  }\n  strength(); localUpdate(); refreshTangent();\n', '  }\n  if (bcKin && !(isA && nn < nrelax)) { real[int] va = V .* bcm, aa = Acc .* bcm; fixBCkin(t);\n    cout << "bckin: prescribed-dof kinematics reset on restart (max |v| " << va.linfty << ", max |a| " << aa.linfty << " before)" << endl; }\n  strength(); localUpdate(); refreshTangent();\n'), ('  f << " \\"mobile_drag\\": {\\"dragrho\\": " << dragRho << ", \\"vc_um_per_ns\\": " << vcrel << ", \\"c1c2c3_MR\\": [" << c1MR << ", " << c2MR << ", " << c3MR << "], \\"rhoMsat\\": " << rhoMsat << ", \\"C2M\\": " << C2M << ", \\"rhoFcut\\": " << rhoFcut << ", \\"rhoMmin\\": " << rhoMmin << ", \\"eta_d\\": \\"B0 (T/T0)/(b^2 rho_m) [sqrt(1+(b tau/(v_c B))^2) if v_c>0]\\"},\\n";\n  f << " \\"robustness\\": {\\"exactexp\\": " << exactExp << ", \\"spinmax\\": " << spinMax << ", \\"spinbranch\\": " << spinBranch << ", \\"onfail\\": \\"" << onFail << "\\", \\"maxit\\": " << maxit << ", \\"maxitretry\\": " << maxitRetry << ", \\"ckroll\\": " << ckRoll << ", \\"dissip_implicit\\": " << dissImp << ", \\"cdstore\\": " << cdStore << ", \\"softmin\\": " << softMin << "},\\n";\n  f << " \\"elastic_law\\": {\\"eos\\": \\"" << eosName << "\\", \\"K0_GPa\\": " << K0eos << ", \\"Kprime\\": " << Kpeos << ", \\"voltan\\": " << volTan << "},\\n";\n', '  f << " \\"mobile_drag\\": {\\"dragrho\\": " << dragRho << ", \\"vc_um_per_ns\\": " << vcrel << ", \\"c1c2c3_MR\\": [" << c1MR << ", " << c2MR << ", " << c3MR << "], \\"rhoMsat\\": " << rhoMsat << ", \\"C2M\\": " << C2M << ", \\"rhoFcut\\": " << rhoFcut << ", \\"rhoMmin\\": " << rhoMmin << ", \\"eta_d\\": \\"B0 (T/T0)/(b^2 rho_m) [sqrt(1+(b tau/(v_c B))^2) if v_c>0]\\"},\\n";\n  f << " \\"robustness\\": {\\"exactexp\\": " << exactExp << ", \\"spinmax\\": " << spinMax << ", \\"spinbranch\\": " << spinBranch << ", \\"bckin\\": " << bcKin << ", \\"predictor\\": \\"" << predName << "\\", \\"onfail\\": \\"" << onFail << "\\", \\"maxit\\": " << maxit << ", \\"maxitretry\\": " << maxitRetry << ", \\"ckroll\\": " << ckRoll << ", \\"dissip_implicit\\": " << dissImp << ", \\"cdstore\\": " << cdStore << ", \\"softmin\\": " << softMin << "},\\n";\n  f << " \\"elastic_law\\": {\\"eos\\": \\"" << eosName << "\\", \\"K0_GPa\\": " << K0eos << ", \\"Kprime\\": " << Kpeos << ", \\"voltan\\": " << volTan << "},\\n";\n'), ('  strength();\n  // predictor (average acceleration)\n  tv = V; tv *= dt; U += tv; tv = Acc; tv *= 0.25*dt*dt; U += tv;\n  if (isP && !relax) { U = U .* pistk; U = U .* confk; tv = pistm; tv *= -pistonDisp(t); U += tv; }   // prescribed piston displacement (x) on the right edge\n', '  strength();\n  // predictor: -predictor avg (old: average acceleration, U + dt V + dt^2/4 A) | vel (U + dt V) | none (U).  Only the starting\n  // guess of the global Newton: with -newton full the converged step does not depend on it; vel/none avoid amplifying a stiff\n  // alternating acceleration mode into a kink (dt^2/4 A) before the first iteration.\n  if (predName != "none") { tv = V; tv *= dt; U += tv; }\n  if (predName == "avg") { tv = Acc; tv *= 0.25*dt*dt; U += tv; }\n  if (isP && !relax) { U = U .* pistk; U = U .* confk; tv = pistm; tv *= -pistonDisp(t); U += tv; }   // prescribed piston displacement (x) on the right edge\n'), ('  tv = Acc; tv += Anew; tv *= 0.5*dt; V += tv; Acc = Anew;\n  // external work (trapezoidal in load)\n', '  tv = Acc; tv += Anew; tv *= 0.5*dt; V += tv; Acc = Anew;\n  if (bcKin && !relax) fixBCkin(t);   // exact kinematics on the prescribed dofs (-bckin)\n  // external work (trapezoidal in load)\n')]
for a, b in P:
    if s.count(a) != 1: sys.exit(fn + ': expected text not found (%d): %r' % (s.count(a), a[:80]))
    s = s.replace(a, b)
open(fn + '.new', 'w').write(s); os.replace(fn + '.new', fn); print(fn, ': patched')
for fn, a, b in [('run_piston_mob.sh', '-spinbranch ${SPINBRANCH:-0.785398} ', '-spinbranch ${SPINBRANCH:-0.785398} -bckin ${BCKIN:-1} -predictor ${PREDICTOR:-vel} '),
                 ('submit_piston_mob.sh', ' SPINMAX SPINBRANCH ', ' SPINMAX SPINBRANCH BCKIN PREDICTOR '),
                 ('run_all_A.sh', ' SPINMAX SPINBRANCH ', ' SPINMAX SPINBRANCH BCKIN PREDICTOR ')]:
    if not os.path.exists(fn): continue
    t = open(fn).read()
    if 'BCKIN' in t or 'bckin' in t: print(fn, ': already patched'); continue
    if t.count(a) != 1: sys.exit(fn + ': expected text not found')
    open(fn + '.new', 'w').write(t.replace(a, b)); os.replace(fn + '.new', fn); print(fn, ': patched')
PYEOF
